"""Independent miniature containers, not generated by product write functions."""

from __future__ import annotations

import struct
import zlib


def script_bytes(payload=b"stored-script", entry_id=4007):
    r1 = 17
    r2 = ((r1 * entry_id + 0xDF25E) & 0xFFFFFFFF) ^ len(payload)
    # Directory index zero cancels the r2 multiplier in the offset transform.
    r3 = 0xD59D16C ^ 16
    return (
        struct.pack("<4sIII", b"0SLF", 1, 16 + len(payload), 0)
        + payload
        + struct.pack("<IIII", entry_id, r1, r2, r3)
    )


def data_bytes():
    contents = [b"", b"ordinary-content"]
    names = ["check\\", "check\\sample.pyc"]
    header = b"FLS\0" + bytes(60)
    local, records = bytearray(), bytearray()
    for name, content in zip(names, contents, strict=True):
        stored = zlib.compress(content)[2:-4] if content else b""
        offset = 64 + len(local)
        crc = zlib.crc32(content)
        local.extend(
            struct.pack(
                "<IHIII",
                0xA0975237,
                8 if content else 0,
                crc,
                len(stored),
                len(content),
            )
            + stored
        )
        name_raw = bytes(c ^ 0xA5 for c in name.encode("gbk"))
        records.extend(
            struct.pack(
                "<IHHHIIIIH",
                0x87F2017C,
                8,
                0,
                0,
                crc,
                len(stored),
                len(content),
                offset,
                len(name_raw),
            )
        )
        records.extend(name_raw)
    return header + local + records + struct.pack("<II", 64 + len(local), 0xA1985237)
